#!/usr/bin/python3
"""Keep the original Kodi launcher; disable this pinned hotfix after an upgrade.

systemd binds the corrected executable only inside kodi.service's namespace.
Never mutate the host's firmware, mount table, launcher, or library paths.
"""
import hashlib
import os
from pathlib import Path
import subprocess
import sys

BASE='793194b0e506a61ab2f1a065fb7dd0395c80d281fe853e48f1150adbc2879b2e'
FIX='8962740e718a7978acadbf2ae7ad55b0cd0742f6d0db162e9c1a1d8645ef834b'
LAUNCHER='3ef81cccd828b86368ff1ca05816ad9c6b282d93f41817a20b4d90fcb9b8fb44'
TARGET='/usr/lib/kodi/kodi.bin'


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def compatible(base,fix,launcher):
    return base==BASE and fix==FIX and launcher==LAUNCHER


def main():
    private=os.readlink('/proc/self/ns/mnt')!=os.readlink('/proc/1/ns/mnt')
    if not private:
        raise RuntimeError('HOTFIX_REQUIRES_SERVICE_PRIVATE_NAMESPACE')
    original='/proc/1/root'+TARGET
    if not compatible(sha(original),sha(TARGET),sha('/usr/lib/kodi/kodi.sh')):
        # Executed only in this service namespace. Reveals the host's original
        # executable after an OS/Kodi upgrade; do not shadow a newer firmware.
        subprocess.run(['/bin/umount',TARGET],check=True,timeout=5)
        if sha(TARGET)!=sha(original):
            raise RuntimeError('HOTFIX_FALLBACK_VERIFICATION_FAILED')
        print('AM6B subtitle284: baseline changed; using system Kodi without this hotfix',flush=True)
    else:
        print('AM6B subtitle284: version-pinned window-ownership and network-scan hotfixes active',flush=True)
    os.execv('/usr/lib/kodi/kodi.sh',['/usr/lib/kodi/kodi.sh',*sys.argv[1:]])


if __name__=='__main__':main()
